{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Earnings Prep Data",
    "url": "http://localhost:7805",
    "widgets_json": {
      "earnings_chart": {
        "name": "EPS History",
        "description": "Plotly EPS beat/miss history",
        "endpoint": "/eps-history",
        "type": "chart",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "raw": true,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ]
      },
      "surprise_metric": {
        "name": "Avg Surprise",
        "description": "Average EPS surprise last 4 quarters",
        "endpoint": "/avg-surprise",
        "type": "metric",
        "w": 6,
        "h": 4,
        "staleTime": 900000
      },
      "estimate_revisions": {
        "name": "Estimate Revisions",
        "description": "Street estimate revisions by quarter",
        "endpoint": "/estimate-revisions",
        "type": "table",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "quarter",
              "headerName": "Quarter",
              "cellDataType": "text"
            },
            {
              "field": "eps_estimate",
              "headerName": "EPS Est",
              "cellDataType": "number"
            },
            {
              "field": "revenue_estimate_b",
              "headerName": "Revenue Est ($B)",
              "cellDataType": "number"
            }
          ]
        }
      }
    },
    "apps_json": [
      {
        "name": "Earnings Chart Live",
        "description": "EPS chart and surprise metric",
        "tabs": {
          "earnings": {
            "id": "earnings",
            "name": "Earnings",
            "layout": [
              {
                "i": "earnings_chart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "signals": {
            "id": "signals",
            "name": "Signals",
            "layout": [
              {
                "i": "surprise_metric",
                "x": 0,
                "y": 0,
                "w": 8,
                "h": 5
              }
            ]
          }
        }
      }
    ]
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "operation": "instantiate",
    "app_name": "Earnings Chart Live",
    "backend_id": "backend_001",
    "dashboard_name": "Earnings Chart Live Board"
  }
}

{
  "done": false,
  "tool": "add_generative_widget",
  "args": {
    "dashboard_id": "dash_002",
    "data": "Earnings Chart Live shipped from Earnings Prep Data: EPS chart live.",
    "name": "Earnings Chart Live",
    "widget_type": "note"
  }
}
